        })
        .collect();
    assert_eq!(changeset_files.len(), 1);

    // 3. Run status
    let status_res = commands::status::handle(
        StatusArgs {
            strict: false,
            check: false,
        },
        &global,
    );
    assert!(status_res.is_ok());
}

