#[non_exhaustive]
pub enum ParseError {
    /// The file does not open with a `---` delimiter on line 1 at all.
    #[error("changeset does not start with a `---` frontmatter delimiter on line 1")]
    #[diagnostic(
        code(E040),
        help("Add a `---` frontmatter delimiter on line 1 of the changeset file.")
    )]
    MissingFrontmatterStart,

    /// A `---` opened on line 1 but no matching closing `---` line was ever found.
    #[error("frontmatter opened with `---` on line 1 but was never closed with a matching `---`")]
    #[diagnostic(code(E041), help("Ensure frontmatter block closes with `---`."))]
    UnclosedFrontmatter,

    /// A quoted name's opening `"` has no matching closing `"` on the same line.

    #[error("failed to read {}: {message}", .path.display())]
    #[diagnostic(
        code(E115),
        help("Check that the file named above is readable. Delete it and re-run `callisto pre enter` to recover.")
    )]
    PreJsonRead { path: std::path::PathBuf, message: String },

    #[error("package `{package}` declares platform targets via both `{napi_source}` and `{maturin_source}`; only one source is allowed")]
    #[diagnostic(
        code(E118),
        help("Remove one of the two target declarations -- either napi.targets in package.json or [tool.maturin].targets in pyproject.toml -- from the package's manifest.")
    )]
    ConflictingPlatformTargetSources {
        package: PackageId,
        napi_source: &'static str,
        maturin_source: &'static str,
    },

    #[error("package `{package}` declares platform targets via `{source_field}` and ships `[[release.artifact]]` binaries; only one is allowed")]
    #[diagnostic(
        code(E203),
        help("Build the native addon and the release binaries from separate packages, or drop one of the two declarations.")
    )]
    PlatformTargetsWithReleaseArtifacts { package: PackageId, source_field: String },

